bool CellularSetup_StartActivation_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::CellularSetup_StartActivation_ResponseParams_Data* params =
      reinterpret_cast<
          internal::CellularSetup_StartActivation_ResponseParams_Data*>(
              message->mutable_payload());
  
  bool success = true;
  ::mojo::PendingRemote<CarrierPortalHandler> p_observer{};
  CellularSetup_StartActivation_ResponseParamsDataView input_data_view(params, message);
  
  if (success) {
    p_observer =
        input_data_view.TakeObserver<decltype(p_observer)>();
  }
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        CellularSetup::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run(
std::move(p_observer));
  return true;
}

void CellularSetup_StartActivation_ProxyToResponder::Run(
    ::mojo::PendingRemote<CarrierPortalHandler> in_observer) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply ash::cellular_setup::mojom::CellularSetup::StartActivation", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("observer"), in_observer,
                        "<value of type ::mojo::PendingRemote<CarrierPortalHandler>>");
   });
#endif
  
  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt);
  
  mojo::Message message(
      internal::kCellularSetup_StartActivation_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::ash::cellular_setup::mojom::internal::CellularSetup_StartActivation_ResponseParams_Data> params(
          message);
  params.Allocate();
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::ash::cellular_setup::mojom::CarrierPortalHandlerInterfaceBase>>(
      in_observer, &params->observer, &params.message());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      !mojo::internal::IsHandleOrInterfaceValid(params->observer),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
      "invalid observer in ");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(CellularSetup::Name_);
  message.set_method_name("StartActivation");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

