// static
bool StructTraits<::ash::cellular_setup::mojom::CellularMetadata::DataView, ::ash::cellular_setup::mojom::CellularMetadataPtr>::Read(
    ::ash::cellular_setup::mojom::CellularMetadata::DataView input,
    ::ash::cellular_setup::mojom::CellularMetadataPtr* output) {
  bool success = true;
  ::ash::cellular_setup::mojom::CellularMetadataPtr result(::ash::cellular_setup::mojom::CellularMetadata::New());
  
      if (success && !input.ReadPaymentUrl(&result->payment_url))
        success = false;
      if (success && !input.ReadPaymentPostData(&result->payment_post_data))
        success = false;
      if (success && !input.ReadCarrier(&result->carrier))
        success = false;
      if (success && !input.ReadMeid(&result->meid))
        success = false;
      if (success && !input.ReadImei(&result->imei))
        success = false;
      if (success && !input.ReadMdn(&result->mdn))
        success = false;
  *output = std::move(result);
  return success;
}

